#!/usr/bin/env node
/**
 * Build a static portrait cache for catalogue artists.
 *
 * Hololive members prefer the official promotional artwork generated by
 * update-talent-artwork.mjs. For other credited artists, reuse the matching
 * YouTube channel's profile avatar and store a small local WebP/PNG/JPEG copy
 * so site visitors do not depend on an external avatar API rate limit.
 *
 * The network lookup is best-effort: a missing avatar never removes an artist
 * and must never fail a GitHub Pages deployment.
 */
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { collectArtistDirectory } from '../scripts/artist-directory.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SONGS_PATH = path.join(ROOT, 'data', 'songs.json');
const TALENTS_PATH = path.join(ROOT, 'data', 'talents.json');
const OUTPUT_PATH = path.join(ROOT, 'data', 'artist-portraits.json');
const AVATAR_DIR = path.join(ROOT, 'assets', 'artist-avatars');
const PROVIDER_BASE = 'https://banner.yt/';
const BATCH_SIZE = 9;
const BATCH_PAUSE_MS = 31_000;
const REQUEST_TIMEOUT_MS = 20_000;
const IMAGE_EXTENSIONS = ['webp', 'png', 'jpg', 'jpeg'];

const wait = ms => new Promise(resolve => setTimeout(resolve, ms));

async function readJson(file, fallback) {
  try { return JSON.parse(await readFile(file, 'utf8')); }
  catch { return fallback; }
}
async function existingAvatarMap() {
  const result = new Map();
  try {
    for (const filename of await readdir(AVATAR_DIR)) {
      const match = filename.match(/^(UC[A-Za-z0-9_-]{22})\.(webp|png|jpe?g)$/i);
      if (match) result.set(match[1], filename);
    }
  } catch {}
  return result;
}
function extensionForMime(contentType) {
  const mime = String(contentType || '').split(';')[0].trim().toLowerCase();
  if (mime === 'image/webp') return 'webp';
  if (mime === 'image/png') return 'png';
  if (mime === 'image/jpeg' || mime === 'image/jpg') return 'jpg';
  return '';
}
function retryDelay(response, attempt) {
  const seconds = Number(response?.headers?.get('retry-after'));
  return Number.isFinite(seconds) && seconds > 0
    ? Math.max(BATCH_PAUSE_MS, Math.ceil(seconds * 1000))
    : BATCH_PAUSE_MS * attempt;
}

async function downloadAvatar(channelId) {
  const url = new URL(encodeURIComponent(channelId), PROVIDER_BASE);
  url.searchParams.set('type', 'avatar');
  url.searchParams.set('format', 'webp');
  url.searchParams.set('width', '128');
  url.searchParams.set('height', '128');

  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    try {
      const response = await fetch(url, {
        headers: { Accept: 'image/webp,image/png,image/jpeg,image/*;q=0.8' },
        signal: controller.signal,
      });
      if (response.status === 429 || response.status >= 500) {
        if (attempt < 3) {
          console.warn('[Artist artwork] HTTP ' + response.status + ' for ' + channelId +
            '; retrying after a provider cooldown.');
          await wait(retryDelay(response, attempt));
          continue;
        }
        return null;
      }
      if (!response.ok) {
        console.warn('[Artist artwork] Skipping ' + channelId + ' (HTTP ' + response.status + ').');
        return null;
      }

      const extension = extensionForMime(response.headers.get('content-type'));
      if (!extension) {
        console.warn('[Artist artwork] Skipping ' + channelId + ' (unexpected content type).');
        return null;
      }
      const bytes = Buffer.from(await response.arrayBuffer());
      if (bytes.length < 128 || bytes.length > 2_000_000) {
        console.warn('[Artist artwork] Skipping ' + channelId + ' (unexpected image size).');
        return null;
      }

      await mkdir(AVATAR_DIR, { recursive: true });
      const filename = channelId + '.' + extension;
      await writeFile(path.join(AVATAR_DIR, filename), bytes);
      return filename;
    } catch (error) {
      if (attempt === 3) {
        console.warn('[Artist artwork] Could not fetch ' + channelId + ': ' + error.message);
        return null;
      }
      await wait(Math.min(5000 * attempt, 15000));
    } finally {
      clearTimeout(timer);
    }
  }
  return null;
}

const catalogue = await readJson(SONGS_PATH, null);
if (!catalogue || !Array.isArray(catalogue.songs)) {
  throw new Error('Cannot build artist portraits: data/songs.json is missing or invalid.');
}
const talentDocument = await readJson(TALENTS_PATH, { talents: [] });
const talents = Array.isArray(talentDocument?.talents) ? talentDocument.talents : [];
const directory = collectArtistDirectory(catalogue.songs, talents);

await mkdir(AVATAR_DIR, { recursive: true });
const cached = await existingAvatarMap();
const pending = [...new Map(
  directory
    .filter(artist => !artist.official && artist.channelId && !cached.has(artist.channelId))
    .map(artist => [artist.channelId, artist]),
).values()];

console.log('[Artist artwork] ' + directory.length + ' distinct artist credits; ' +
  directory.filter(artist => artist.official).length + ' use official talent artwork; ' +
  cached.size + ' channel avatars already cached; ' + pending.length + ' to fetch.');

let downloaded = 0;
let failed = 0;
for (let offset = 0; offset < pending.length; offset += BATCH_SIZE) {
  const batch = pending.slice(offset, offset + BATCH_SIZE);
  const results = await Promise.all(batch.map(async artist => ({
    artist,
    filename: await downloadAvatar(artist.channelId),
  })));
  let successesThisBatch = 0;
  for (const { artist, filename } of results) {
    if (filename) {
      cached.set(artist.channelId, filename);
      downloaded += 1;
      successesThisBatch += 1;
    } else {
      failed += 1;
    }
  }
  console.log('[Artist artwork] Processed ' + Math.min(offset + batch.length, pending.length) +
    '/' + pending.length + ' new channel avatars (' + downloaded + ' downloaded, ' + failed + ' unavailable).');

  // banner.yt documents a 10-request/30-second anonymous limit. The cache
  // normally makes this a no-op for previously downloaded channels.
  if (offset + batch.length < pending.length) {
    if (successesThisBatch === 0) {
      console.warn('[Artist artwork] No avatars succeeded in this batch; stopping new lookups to keep deployment reliable.');
      break;
    }
    await wait(BATCH_PAUSE_MS);
  }
}

const images = {};
for (const artist of directory) {
  if (artist.official || !artist.channelId) continue;
  const filename = cached.get(artist.channelId);
  if (filename) images[artist.name] = 'assets/artist-avatars/' + filename;
}

const missingPortraits = directory.filter(artist => !artist.official && !images[artist.name]);

await writeFile(OUTPUT_PATH, JSON.stringify({
  schemaVersion: 1,
  generatedAt: new Date().toISOString(),
  source: 'Holodex catalogue artist credits; official Hololive artwork preferred, otherwise cached YouTube channel avatars',
  artistCount: directory.length,
  avatarCount: Object.keys(images).length,
  images,
}, null, 2) + '\n');

console.log('[Artist artwork] Wrote ' + Object.keys(images).length + ' cached avatar mappings for ' +
  directory.length + ' catalogue artists.');
if (missingPortraits.length) {
  console.log('[Artist artwork] Guest/collaborator credits without a portrait (' + missingPortraits.length + '):');
  for (const artist of missingPortraits) {
    const reason = !artist.channelId
      ? 'no matching YouTube channel ID found in catalogue metadata'
      : !cached.has(artist.channelId)
        ? 'channel avatar was not downloaded or cached'
        : 'channel avatar exists but no name mapping was generated';
    console.log('[Artist artwork] MISSING: ' + artist.name + ' — ' + reason);
  }
} else {
  console.log('[Artist artwork] All non-official artist credits have a portrait mapping.');
}
